import{_ as a,c as r,o as t,a5 as o}from"./chunks/framework.BmNIwhaK.js";const p=JSON.parse('{"title":"全社技術用語集 (SyncSeries Technical Glossary)","description":"株式会社エムパシー（Empasy）のSyncSeries全社アーキテクチャおよび11製品群で使用する主要技術用語（MCP、A2A、AgentScope Java、NL2SQL、RAG/GraphRAG、pgvector、HITL、eBPF、WAF、RBAC、Zero-Mock、Canonical URL、MSA、Playwright Self-Healing、CVSS/CVE/STIX、FinOps、Semantic Cache）の公式技術定義単一情報源（SSOT）です。","frontmatter":{"title":"全社技術用語集 (SyncSeries Technical Glossary)","sidebarTitle":"全社技術用語集","description":"株式会社エムパシー（Empasy）のSyncSeries全社アーキテクチャおよび11製品群で使用する主要技術用語（MCP、A2A、AgentScope Java、NL2SQL、RAG/GraphRAG、pgvector、HITL、eBPF、WAF、RBAC、Zero-Mock、Canonical URL、MSA、Playwright Self-Healing、CVSS/CVE/STIX、FinOps、Semantic Cache）の公式技術定義単一情報源（SSOT）です。","head":[["meta",{"name":"keywords","content":"技術用語集, SyncSeries Glossary, MCP, A2A, AgentScope Java, NL2SQL, RAG, GraphRAG, pgvector, HITL, eBPF, WAF, RBAC, Zero-Mock, Canonical URL, MSA, Playwright Self-Healing, CVSS, CVE, STIX, FinOps, Semantic Cache, エムパシー, 株式会社エムパシー, Empasy"}],["meta",{"property":"og:title","content":"全社技術用語集 (SyncSeries Technical Glossary) | Empasy Docs"}],["meta",{"property":"og:description","content":"株式会社エムパシー（Empasy）のSyncSeries全社アーキテクチャおよび11製品群で使用する主要技術用語（MCP、A2A、AgentScope Java、NL2SQL、RAG/GraphRAG、pgvector、HITL、eBPF、WAF、RBAC、Zero-Mock、Canonical URL、MSA、Playwright Self-Healing、CVSS/CVE/STIX、FinOps、Semantic Cache）の公式技術定義単一情報源（SSOT）です。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/glossary/"}],["meta",{"name":"robots","content":"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/glossary/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/glossary/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/glossary/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/glossary/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/glossary/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"全社技術用語集 (SyncSeries Technical Glossary) | Empasy Docs"}],["meta",{"name":"twitter:description","content":"株式会社エムパシー（Empasy）のSyncSeries全社アーキテクチャおよび11製品群で使用する主要技術用語（MCP、A2A、AgentScope Java、NL2SQL、RAG/GraphRAG、pgvector、HITL、eBPF、WAF、RBAC、Zero-Mock、Canonical URL、MSA、Playwright Self-Healing、CVSS/CVE/STIX、FinOps、Semantic Cache）の公式技術定義単一情報源（SSOT）です。"}],["script",{"type":"application/ld+json","data-empasy-page-jsonld":"true"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"全社技術用語集 (SyncSeries Technical Glossary)\\",\\"description\\":\\"株式会社エムパシー（Empasy）のSyncSeries全社アーキテクチャおよび11製品群で使用する主要技術用語（MCP、A2A、AgentScope Java、NL2SQL、RAG/GraphRAG、pgvector、HITL、eBPF、WAF、RBAC、Zero-Mock、Canonical URL、MSA、Playwright Self-Healing、CVSS/CVE/STIX、FinOps、Semantic Cache）の公式技術定義単一情報源（SSOT）です。\\",\\"url\\":\\"https://doc.empasy.com/ja/glossary/\\",\\"inLanguage\\":\\"ja-JP\\",\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://doc.empasy.com/ja/glossary/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://doc.empasy.com/images/favicon.png\\"}}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Empasy Docs (JA)\\",\\"item\\":\\"https://doc.empasy.com/ja/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"全社技術用語集 (SyncSeries Technical Glossary)\\",\\"item\\":\\"https://doc.empasy.com/ja/glossary/\\"}]}]}"]],"sort":1},"headers":[],"relativePath":"ja/glossary/index.md","filePath":"ja/glossary/index.md","lastUpdated":1795595391000}'),n={name:"ja/glossary/index.md"};function s(i,e,l,c,h,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="全社技術用語集-syncseries-technical-glossary" tabindex="-1">全社技術用語集 (SyncSeries Technical Glossary) <a class="header-anchor" href="#全社技術用語集-syncseries-technical-glossary" aria-label="Permalink to “全社技術用語集 (SyncSeries Technical Glossary)”">​</a></h1><blockquote><p><strong>文書の位置づけについて</strong>: 本ページは、<code>doc.empasy.com</code> が管理する<strong>株式会社エムパシー（Empasy）および SyncSeries 公式技術用語の単一情報源（SSOT）</strong>です。非開発者・導入検討担当者向けの製品紹介については、<a href="https://empasy.io/ja/pages/index.html" target="_blank" rel="noreferrer">エムパシー公式ホームページ（empasy.io）</a>および<a href="https://demo.empasy.io/ja/" target="_blank" rel="noreferrer">統合デモポータル（sync.empasy.io）</a>をご参照ください。</p></blockquote><hr><h2 id="クイックインデックス" tabindex="-1">クイックインデックス <a class="header-anchor" href="#クイックインデックス" aria-label="Permalink to “クイックインデックス”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">分類</th><th style="text-align:left;">収録用語</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>エージェント・オーケストレーション</strong></td><td style="text-align:left;"><a href="#mcp">MCP</a> · <a href="#a2a">A2A</a> · <a href="#agentscope-java">AgentScope Java</a> · <a href="#hitl">HITL</a></td></tr><tr><td style="text-align:left;"><strong>データ・検索・LLM 運用</strong></td><td style="text-align:left;"><a href="#nl2sql">NL2SQL</a> · <a href="#rag-graphrag">RAG / GraphRAG</a> · <a href="#pgvector">pgvector</a> · <a href="#finops">FinOps</a> · <a href="#semantic-cache">Semantic Cache</a></td></tr><tr><td style="text-align:left;"><strong>アーキテクチャ・開発標準</strong></td><td style="text-align:left;"><a href="#canonical-url">Canonical URL</a> · <a href="#msa">MSA</a> · <a href="#rbac">RBAC</a> · <a href="#zero-mock">Zero-Mock</a></td></tr><tr><td style="text-align:left;"><strong>セキュリティ・品質自動化</strong></td><td style="text-align:left;"><a href="#ebpf">eBPF</a> · <a href="#waf">WAF</a> · <a href="#cvss-cve-stix">CVSS / CVE / STIX</a> · <a href="#playwright-self-healing">Playwright Self-Healing</a></td></tr></tbody></table><hr><h2 id="_1-エージェント・オーケストレーション" tabindex="-1">1. エージェント・オーケストレーション <a class="header-anchor" href="#_1-エージェント・オーケストレーション" aria-label="Permalink to “1. エージェント・オーケストレーション”">​</a></h2><h3 id="mcp" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp" aria-label="Permalink to “MCP (Model Context Protocol)”">​</a></h3><ul><li><strong>概要</strong>: AIエージェントと業務システム・ツール間の標準通信規格です。</li><li><strong>技術定義</strong>: JSON-RPC 2.0をベースとし、LLMおよびエージェントランタイムが外部ツール（Tool）、リソース（Resource）、プロンプト（Prompt）を標準化されたスキーマで探索・呼び出しできるようにするオープンプロトコルです。SyncSeriesのすべてのドメインモジュールは、SSEまたはStreamable HTTPトランスポート層を介して標準MCPツールを公開します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/ecosystem/mcp-protocol">標準MCPプロトコル仕様</a> · <a href="/ja/sdk/custom-mcp-tool">カスタムMCPツール開発</a> · <a href="/ja/syncverse/mcp-tool-registry">SyncVerse MCPレジストリ</a></li></ul><h3 id="a2a" tabindex="-1">A2A (Agent-to-Agent) <a class="header-anchor" href="#a2a" aria-label="Permalink to “A2A (Agent-to-Agent)”">​</a></h3><ul><li><strong>概要</strong>: 各業務領域を担当するソフトウェアモジュール（エージェント）同士がタスクをやり取りする協調構造です。</li><li><strong>技術定義</strong>: 中央管制オーケストレーター（<code>SyncVerse</code>）が上位のビジネスリクエストを下位のタスク単位（DAG）に分解し、各ドメインエージェント（<code>SyncBoot</code>、<code>SyncCMS</code>、<code>SyncShop</code>、<code>SyncInsight</code>、<code>SyncAPIM</code>、<code>SyncWatch</code>、<code>SyncOps</code>、<code>SyncETA</code>、<code>SyncCrawl</code>、<code>SyncLLM</code>）間で非同期メッセージおよびステータスイベントを交換しながら完了まで調停する分散エージェント協調アーキテクチャです。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/ecosystem/">SyncSeries エコシステムアーキテクチャ</a> · <a href="/ja/ecosystem/e2e-workflow">モジュール間 E2E 連携シナリオ</a> · <a href="/ja/syncverse/architecture">SyncVerse アーキテクチャ</a></li></ul><h3 id="agentscope-java" tabindex="-1">AgentScope Java <a class="header-anchor" href="#agentscope-java" aria-label="Permalink to “AgentScope Java”">​</a></h3><ul><li><strong>概要</strong>: Java（Spring Boot）環境においてAI推論とツール呼び出しを安定して実行するための標準フレームワークです。</li><li><strong>技術定義</strong>: SyncSeries全社のJava 25・Spring Boot 4.0バックエンドで採用している単一のAIエージェントランタイム（<code>io.agentscope:agentscope-harness</code>）です。<code>ReActAgent</code>ベースの推論・行動ループ、<code>MsgHub</code>ベースのマルチエージェントメッセージブロードキャスト、構造化ツールバインディングを提供し、DBトランザクション（<code>@Transactional</code>）と長時間のLLM/MCP I/O境界を明確に分離して運用します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/ecosystem/agentscope-guide">AgentScope Java 標準ガイド</a> · <a href="/ja/syncboot/agentscope-integration">SyncBoot AgentScope 連携実務</a> · <a href="/ja/study/springboot-virtual-threads-agentscope">仮想スレッド &amp; AgentScope 研究</a></li></ul><h3 id="hitl" tabindex="-1">HITL (Human-in-the-Loop) <a class="header-anchor" href="#hitl" aria-label="Permalink to “HITL (Human-in-the-Loop)”">​</a></h3><ul><li><strong>概要</strong>: 重要な変更やデプロイの前に、担当者が直接レビューし承認・却下を行う安全プロセスです。</li><li><strong>技術定義</strong>: AIエージェントの実行権限をリスク階層（Tier 1: 読み取り専用の自律実行、Tier 2: 事後通知型のソフト変更、Tier 3: 事前承認必須の高リスク変更）に分類し、DBスキーマ（DDL）変更・権限修正・価格ポリシー反映・本番デプロイといった高リスク作業の前に変更Diffと影響度レポートを提示して、複数名による決裁ラインの承認を強制するガバナンス機構です。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/ecosystem/hitl-governance">HITL ガバナンス &amp; Saga</a> · <a href="/ja/guide/hitl-approval-operations">多段階決裁 &amp; 監査運用ガイド</a> · <a href="/ja/syncverse/hitl-governance">SyncVerse HITL 承認</a></li></ul><hr><h2 id="_2-データ・検索・llm-運用" tabindex="-1">2. データ・検索・LLM 運用 <a class="header-anchor" href="#_2-データ・検索・llm-運用" aria-label="Permalink to “2. データ・検索・LLM 運用”">​</a></h2><h3 id="nl2sql" tabindex="-1">NL2SQL (Natural Language to SQL) <a class="header-anchor" href="#nl2sql" aria-label="Permalink to “NL2SQL (Natural Language to SQL)”">​</a></h3><ul><li><strong>概要</strong>: 日常的な自然言語による質問を、安全なデータベース照会コマンドへ自動変換する技術です。</li><li><strong>技術定義</strong>: ユーザーが入力した自然言語クエリをデータベースのメタデータ・スキーマコンテキストと結合し、実行可能なSQL文として生成する技術です。SyncSeries（<code>sync-module-nl2sql</code>、<code>SyncInsight</code>）は、<strong>Apache Calcite ASTパーサー</strong>を通じて<code>SELECT</code>読み取り専用クエリのみを許可し、<code>INSERT</code>/<code>UPDATE</code>/<code>DELETE</code>/<code>DROP</code>および許可されていないテーブルへのアクセスを構文木段階で根本的に遮断するとともに、強制<code>LIMIT</code>ガードレールを適用します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncinsight/nl2sql-and-data">SyncInsight NL2SQL データ分析</a> · <a href="/ja/ecosystem/shared-modules-and-sdk">共有モジュール &amp; SDK</a></li></ul><h3 id="rag-graphrag" tabindex="-1">RAG / GraphRAG (Retrieval-Augmented Generation) <a class="header-anchor" href="#rag-graphrag" aria-label="Permalink to “RAG / GraphRAG (Retrieval-Augmented Generation)”">​</a></h3><ul><li><strong>概要</strong>: AIが推測で回答せず、社内ドキュメントや知識関係を直接検索して根拠に基づき回答する方式です。</li><li><strong>技術定義</strong>: <ul><li><strong>RAG</strong>: 外部ドキュメント・マニュアル・Web収集データをチャンキング（Chunking）および埋め込み（Embedding）処理し、ベクトル／キーワードのハイブリッド検索によって関連根拠を先に取得した上でLLMプロンプトに注入し、ハルシネーション（Hallucination）を最小化する検索拡張生成手法です。</li><li><strong>GraphRAG</strong>: ドキュメント内のエンティティ（Entity）と関係（Relation）をナレッジグラフ構造として併せて索引化し、単純な類似度検索だけでは結び付けにくい複数ドキュメント間の因果・依存関係を追跡する拡張検索アーキテクチャです。</li></ul></li><li><strong>関連ドキュメント</strong>: <a href="/ja/synccrawl/rag-knowledge-pipeline">SyncCrawl RAG ナレッジパイプライン</a> · <a href="/ja/study/hybrid-rag-dense-sparse-reranking">ハイブリッド RAG &amp; リランキング研究</a> · <a href="/ja/study/rag">RAG パイプライン基礎</a></li></ul><h3 id="pgvector" tabindex="-1">pgvector <a class="header-anchor" href="#pgvector" aria-label="Permalink to “pgvector”">​</a></h3><ul><li><strong>概要</strong>: 専用のベクトルDBを別途導入することなく、PostgreSQL単体で構造化データとAI意味検索を同時に処理する拡張モジュールです。</li><li><strong>技術定義</strong>: PostgreSQL 18.6データベース内で高次元実数ベクトル（<code>vector</code>）カラムの格納とHNSW / IVFFlat近似最近傍（ANN）類似度検索をネイティブにサポートするオープンソース拡張機能です。SyncSeriesは外部ベクトルストアの二重運用を行わず、PostgreSQL 18.6の単一トランザクション境界内でリレーショナルデータ、全文検索（<code>pg_trgm</code>）、ベクトル検索（<code>pgvector</code>）を統合管理します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncboot/h2">SyncBoot PostgreSQL 18.6 ローカル環境</a> · <a href="/ja/synccrawl/architecture">SyncCrawl アーキテクチャ</a> · <a href="/ja/syncops/architecture">SyncOps アーキテクチャ</a></li></ul><h3 id="finops" tabindex="-1">FinOps (AI / Cloud Financial Operations) <a class="header-anchor" href="#finops" aria-label="Permalink to “FinOps (AI / Cloud Financial Operations)”">​</a></h3><ul><li><strong>概要</strong>: 部署・プロジェクト別のAI利用量とクラウドコストをリアルタイムに集計し、予算上限を統制する管理体系です。</li><li><strong>技術定義</strong>: マルチLLM（商用APIおよびオンプレミスオープンソースモデル）の呼び出し時に発生する入力・出力トークン数、モデル単価、リクエスト遅延時間をテナント・部署・プロジェクト単位でリアルタイムに計量し、予算しきい値（例: 80%で警告、100%で遮断または軽量モデルへのダウングレード）に応じて自動ポリシーを執行するコストガバナンスフレームワークです。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncllm/finops-and-cache">SyncLLM FinOps &amp; セマンティックキャッシュ</a> · <a href="/ja/guide/finops-budget-operations">FinOps 予算 &amp; コスト運用ガイド</a> · <a href="/ja/syncverse/finops-and-syncllm">SyncVerse LLM ゲートウェイ</a></li></ul><h3 id="semantic-cache" tabindex="-1">Semantic Cache (セマンティックキャッシュ) <a class="header-anchor" href="#semantic-cache" aria-label="Permalink to “Semantic Cache (セマンティックキャッシュ)”">​</a></h3><ul><li><strong>概要</strong>: 表現が異なっていても意味が同じ過去の質問を再利用し、AIの応答速度を高めてコストを削減する技術です。</li><li><strong>技術定義</strong>: 文字列の完全一致（Exact Match）のみに依存する従来のキャッシュとは異なり、ユーザープロンプトの埋め込みベクトル間のコサイン類似度（Cosine Similarity）が設定しきい値（例: 0.95以上）を満たした場合に、Redis/pgvectorキャッシュに保存された検証済みレスポンスを即座に返却することで、重複するLLM推論コストと応答遅延を削減するキャッシング手法です。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncllm/finops-and-cache">SyncLLM FinOps &amp; セマンティックキャッシュ</a> · <a href="/ja/syncllm/routing-and-gateway">SyncLLM インテリジェントモデルルーティング</a></li></ul><hr><h2 id="_3-アーキテクチャ・開発標準" tabindex="-1">3. アーキテクチャ・開発標準 <a class="header-anchor" href="#_3-アーキテクチャ・開発標準" aria-label="Permalink to “3. アーキテクチャ・開発標準”">​</a></h2><h3 id="canonical-url" tabindex="-1">Canonical URL (全社単一標準APIパス) <a class="header-anchor" href="#canonical-url" aria-label="Permalink to “Canonical URL (全社単一標準APIパス)”">​</a></h3><ul><li><strong>概要</strong>: すべてのモジュールのAPIアドレスを一貫した単一のルールで統一し、連携時の混乱をなくすパス標準です。</li><li><strong>技術定義</strong>: SyncSeries全社のバックエンドコントローラーとフロントエンド呼び出し側が1対1で一致するよう、リソースあたり単一の正規パス（<code>/api/v1/{product}/{resource}</code>）のみをマッピングするAPI設計原則です。複数配列マッピングやプロキシパス変換（rewrite）を禁止することで、APIゲートウェイ、ドキュメント、権限認可、セキュリティ検知（<code>SyncAPIM</code>）間のパス不一致を根本から排除します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncboot/architecture">SyncBoot システムアーキテクチャ</a> · <a href="/ja/syncapim/architecture">SyncAPIM アーキテクチャ</a></li></ul><h3 id="msa" tabindex="-1">MSA (Microservices Architecture) <a class="header-anchor" href="#msa" aria-label="Permalink to “MSA (Microservices Architecture)”">​</a></h3><ul><li><strong>概要</strong>: 注文・決済・検索・認証などの業務機能を独立したサービスに分割し、障害の波及を防いで個別に拡張できるようにする構造です。</li><li><strong>技術定義</strong>: 単一の巨大アプリケーションではなく、ドメイン境界ごとに独立してデプロイ・拡張可能なサービス単位に分離するアーキテクチャです。SyncSeriesでは<code>SyncShop</code>（Gateway、Auth、Admin、Portal、Search、Monitor、MBG、MCP Serverなどの独立モジュール構成）および<code>SyncAPIM</code>（4-JVM性能分離構造）に適用され、高トラフィック処理性能と障害分離を保証します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncshop/architecture">SyncShop システムアーキテクチャ</a> · <a href="/ja/syncapim/architecture">SyncAPIM 4-JVM アーキテクチャ</a></li></ul><h3 id="rbac" tabindex="-1">RBAC (Role-Based Access Control) <a class="header-anchor" href="#rbac" aria-label="Permalink to “RBAC (Role-Based Access Control)”">​</a></h3><ul><li><strong>概要</strong>: 職務や役割に応じて、閲覧可能なメニューや実行可能な機能を制御する権限体系です。</li><li><strong>技術定義</strong>: ユーザーに直接権限を付与せず、ロール（<code>sys_role</code>）とメニュー・機能・ボタン権限（<code>sys_permission</code>、<code>sys_role_permission</code>）をマッピングしてアクセスを制御するセキュリティモデルです。SyncSeries全社のフロントエンドは静的メニューのハードコーディングを行わず、バックエンド認可API（<code>/api/v1/{product}/sys/permission/getUserPermissionByToken</code>）から現在ユーザーの認可ツリーのみを動的に受信します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncboot/enterprise-security">SyncBoot セキュリティ &amp; マルチテナンシー</a> · <a href="/ja/ecosystem/security-and-compliance">セキュリティホワイトペーパー &amp; コンプライアンス</a></li></ul><h3 id="zero-mock" tabindex="-1">Zero-Mock (実戦連携整合性原則) <a class="header-anchor" href="#zero-mock" aria-label="Permalink to “Zero-Mock (実戦連携整合性原則)”">​</a></h3><ul><li><strong>概要</strong>: 偽のデータや暫定レスポンスを用いず、すべての画面と機能が実際のデータベース・サーバーと連携して動作することを検証する品質基準です。</li><li><strong>技術定義</strong>: 本番コードおよびUIにおけるハードコーディングされたダミー配列、空コレクションの返却、例外を握りつぶした上での偽の成功レスポンス（Fake Normalcy）、プロンプト文字列分岐（Prompt Sniffing）を禁止するエンジニアリング品質規律です。障害発生時はRFC 7807 Problem Detailsに基づく明示的なエラーとして透過的に伝播し、自動化された静的・契約検証スクリプトによって継続的に検査します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/ecosystem/zero-mock-harness">Zero-Mock 品質ハーネス</a> · <a href="/ja/sdk/zero-mock-testing">Zero-Mock テストハーネスガイド</a></li></ul><hr><h2 id="_4-セキュリティ・品質自動化" tabindex="-1">4. セキュリティ・品質自動化 <a class="header-anchor" href="#_4-セキュリティ・品質自動化" aria-label="Permalink to “4. セキュリティ・品質自動化”">​</a></h2><h3 id="ebpf" tabindex="-1">eBPF (Extended Berkeley Packet Filter) <a class="header-anchor" href="#ebpf" aria-label="Permalink to “eBPF (Extended Berkeley Packet Filter)”">​</a></h3><ul><li><strong>概要</strong>: OSのカーネルレベルで悪性トラフィックを超低遅延で検知・遮断するLinuxセキュリティ技術です。</li><li><strong>技術定義</strong>: Linuxカーネルのソースを修正したりカーネルモジュールを直接ロードしたりすることなく、サンドボックス検証器を通過したバイトコードをカーネル内のネットワーク・システムコールフック（XDP/TCなど）上で安全に実行する技術です。<code>SyncAPIM</code>では、アプリケーションサーバー（WAS）に到達する前のカーネル境界で攻撃元IP・パターンを高速遮断するために活用しています。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncapim/">SyncAPIM 概要</a> · <a href="/ja/syncapim/waf-and-pii-governance">SyncAPIM WAF 脅威検知 &amp; PII マスキング</a></li></ul><h3 id="waf" tabindex="-1">WAF (Web Application Firewall) <a class="header-anchor" href="#waf" aria-label="Permalink to “WAF (Web Application Firewall)”">​</a></h3><ul><li><strong>概要</strong>: SQLインジェクションやクロスサイトスクリプティング（XSS）などのWeb・API攻撃をリアルタイムに検知して遮断するファイアウォールです。</li><li><strong>技術定義</strong>: HTTP/HTTPSおよびREST/GraphQL APIペイロードをアプリケーション層（L7）で検査し、SQL Injection、XSS、SSRF、Path Traversal、コマンドインジェクション（Command Injection）、認証バイパスなどのWeb脆弱性を悪用する試行を検知・遮断するセキュリティ層です。<code>SyncAPIM</code>は構文トークン解析器（<code>SqlXssLexicalTokenizer</code>）と<code>SyncWatch</code>から配信される仮想パッチルール（<code>ApimDefensePack</code>）を組み合わせることで誤検知を低減します。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncapim/waf-and-pii-governance">SyncAPIM WAF 脅威検知 &amp; PII マスキング</a> · <a href="/ja/syncwatch/architecture">SyncWatch アーキテクチャ &amp; ルールコンパイラ</a></li></ul><h3 id="cvss-cve-stix" tabindex="-1">CVSS / CVE / STIX <a class="header-anchor" href="#cvss-cve-stix" aria-label="Permalink to “CVSS / CVE / STIX”">​</a></h3><ul><li><strong>概要</strong>: 世界中のセキュリティ脆弱性の固有番号（CVE）、危険度スコア（CVSS）、脅威情報交換標準（STIX）です。</li><li><strong>技術定義</strong>: <ul><li><strong>CVE (Common Vulnerabilities and Exposures)</strong>: 公開されたソフトウェアのセキュリティ脆弱性に付与される国際標準の識別番号（例: <code>CVE-2026-XXXXX</code>）です。</li><li><strong>CVSS (Common Vulnerability Scoring System)</strong>: 脆弱性の攻撃難易度・影響範囲を0.0〜10.0の数値（Low/Medium/High/Critical）で定量化する危険度評価体系です。</li><li><strong>STIX (Structured Threat Information Expression)</strong>: サイバー脅威インテリジェンス（攻撃パターン、侵害指標、対応策）を機械可読なJSON構造で交換するための国際標準（OASIS）です。</li></ul></li><li><strong>関連ドキュメント</strong>: <a href="/ja/syncwatch/">SyncWatch 概要</a> · <a href="/ja/syncwatch/devsecops-protocol">SyncWatch Verse &amp; APIM 連携プロトコル</a> · <a href="/ja/syncwatch/api-and-schema">SyncWatch DB スキーマ &amp; API 仕様</a></li></ul><h3 id="playwright-self-healing" tabindex="-1">Playwright Self-Healing (テスト自己修復) <a class="header-anchor" href="#playwright-self-healing" aria-label="Permalink to “Playwright Self-Healing (テスト自己修復)”">​</a></h3><ul><li><strong>概要</strong>: 画面デザインやボタン配置が変更されても自動テストが停止せず、対象要素を再度見つけ出して検証を継続する技術です。</li><li><strong>技術定義</strong>: PlaywrightベースのE2Eブラウザ自動化実行中にUI改修によって既存のCSS/XPathセレクタが失敗した際、セマンティックDOM属性・アクセシビリティツリー（ARIA Role/Label）・視覚的画面解析（Vision-LLM）を段階的に組み合わせて変更後の要素を再探索し、セレクタを自動補正する復旧メカニズムです。</li><li><strong>関連ドキュメント</strong>: <a href="/ja/synceta/self-healing-and-vision">SyncETA 自己修復 &amp; ビジョン</a> · <a href="/ja/study/vision-llm-self-healing-algorithm">Vision-LLM 自己修復アルゴリズム研究</a> · <a href="/ja/synceta/glossary">SyncETA 用語辞典</a></li></ul><hr><h2 id="追加ドメイン別用語辞典" tabindex="-1">追加ドメイン別用語辞典 <a class="header-anchor" href="#追加ドメイン別用語辞典" aria-label="Permalink to “追加ドメイン別用語辞典”">​</a></h2><ul><li><strong><a href="/ja/synceta/glossary">SyncETA テスト自動化用語辞典</a></strong>: ストーリー、シナリオ、データセット、コレクションなどQA自動化専用用語</li><li><strong><a href="/ja/agile/glossaryOfTerms">アジャイルおよび開発工学用語辞典</a></strong>: スクラムバン、WIP、ベロシティ、DoR/DoD、ストーリーポイントなどの協業プロセス用語</li></ul>',50)])])}const S=a(n,[["render",s]]);export{p as __pageData,S as default};
